public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Searches public chats by looking for specified query in their username and title. Currently, only private chats, supergroups and channels can be public. Returns a meaningful number of results.
    /// Excludes private chats with contacts and chats from the chat list from the results
    /// </summary>
    public Task<TdLib.TdApi.Objects.Chats> SearchPublicChatsAsync(string query = default)
    {

           using var activity =  StartCallActivity("SearchPublicChatsAsync", typeof(SearchPublicChats).FullName ?? "SearchPublicChatsAsync");

           try
           {
             return client.SearchPublicChatsAsync(query);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
